  "build.capDamage": "{model}. މި ސައިޓަށްޓަކައި ހެދި ޕްރިވިއު އެނިމޭޝަން. ގޭމުގައި (0.3.0) މޮޑިއުލްތަކަށް ވަކިން ގެއްލުން ލިބެއެވެ، ޖޮއިންޓްތައް ފެއިލްވެ ހަލް ބިދިގެން ދެވެ، ފަހު ޕުޅުތައް ގިރާލަމުން ދެވަނަ ބޮމް ދެއެވެ.",
  "build.capLoadout": "{model}. މި ސައިޓަށްޓަކައި ކުރެހި ޝީލްޑް ބަބަލް؛ ގޭމުގައި ޝީލްޑަށް ހިޓް ލިބުމުން އެ ފެންނަ.",
  "build.colour.customLabel": "ޝީލްޑުގެ ކަސްޓަމް ކުލަ",
  "build.colour.customNote": "ކަސްޓަމް ކުލައެއް ލޯޑައުޓް ސްޓްރިންގއަށް ލިޔެވެނީ ހަ ހެކްސް ޑިޖިޓެއްގެ ގޮތުގައެވެ.",
  "build.colour.legend": "ޝީލްޑުގެ ކުލަ",
  "build.colour.say": "ޝީލްޑުގެ ކުލަ {name}.",
  "build.colour.sayCustom": "ޝީލްޑުގެ ކަސްޓަމް ކުލަ.",
  "build.colour.tooDark": "އެ ކުލަ ވަރަށް އަނދިރި: އޭގެ އެންމެ އަލި ޗެނަލް 0x{hex} އަށްވުރެ ދަށުގައި، އެހެންވެ ގޭމުން އެ STOCK ގެ ގޮތުގައި ކިޔާ، އަދި ޝީލްޑަށް ސްޓޮކް ކުލަ ބެހެއްޓެއެވެ.",
  "build.configuratorNeedsJavascript": "ކޮންފިގިއުރޭޓަރަށް ޖާވާސްކްރިޕްޓް ބޭނުންވެއެވެ، އެއީ މިތަނުގައި ނިވިފައި. ގޭމުގެ LOADOUT ސްކްރީނުން ހަލްގެ ތިން ފެންވަރު (ސްޓޭންޑަޑް، ރިއިންފޯސްޑް، ބަލްވޯކް)، ޝީލްޑުގެ ތިން ފެންވަރު (ސްޓޭންޑަޑް، ހާޑެންޑް، ޑީޕް-ފީލްޑް)، ޝީލްޑުގެ އަށް ކުލައާއި ކަސްޓަމް ކުލައެއް، ކޮންމެ ހާޑްޕޮއިންޓަކަށް ފިޓާއި މޯޑު، އަދި ANVIL ގައި ހޭންގަރުން ނިކުންނަ ކްރާފްޓް ދެއެވެ.",
